// Selects the appointments that need a reminder now and builds each email.
// Edit the subject and body in the "EMAIL TEXT" block near the end.
const cfg = $('Set business settings').first().json;

// ===== Helpers (no need to edit) =====
const ZONE = cfg.timezone || 'UTC';
const LOCALE = cfg.locale || 'en';
const DAY_FIRST = !/^MM/i.test(String(cfg.date_format || 'DD/MM/YYYY').trim());
const SKIP_STATUSES = ['cancelled', 'canceled', 'completed', 'no_show', 'noshow'];

// Accepts YYYY-MM-DD, DD/MM/YYYY or MM/DD/YYYY (see date_format), Sheets serial numbers,
// and times like 10:30, 10.30, 10h30, 10:30:00, 2:30 PM or a Sheets time fraction (0.4375).
function parseAppointment(row) {
  const d = String(row.date ?? '').trim();
  const t = String(row.time ?? '').trim();
  let y, m, day, mm;
  if ((mm = d.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/))) { y = +mm[1]; m = +mm[2]; day = +mm[3]; }
  else if ((mm = d.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/))) {
    day = DAY_FIRST ? +mm[1] : +mm[2]; m = DAY_FIRST ? +mm[2] : +mm[1]; y = +mm[3]; if (y < 100) y += 2000;
  }
  else if (/^\d+(\.\d+)?$/.test(d)) {
    const b = DateTime.fromObject({ year: 1899, month: 12, day: 30 }, { zone: ZONE }).plus({ days: Math.floor(+d) });
    y = b.year; m = b.month; day = b.day;
  }
  else return null;
  let hour = 0, minute = 0, tm;
  if (/^0?\.\d+$/.test(t)) { const mins = Math.round(+t * 1440); hour = Math.floor(mins / 60); minute = mins % 60; }
  else if ((tm = t.match(/^(\d{1,2})(?:[:.h](\d{2}))?(?::\d{2})?\s*([ap])?\.?\s*m?\.?$/i))) {
    hour = +tm[1]; minute = +(tm[2] || 0);
    const ap = (tm[3] || '').toLowerCase();
    if (ap === 'p' && hour < 12) hour += 12;
    if (ap === 'a' && hour === 12) hour = 0;
  }
  else if (t) return null;
  const dt = DateTime.fromObject({ year: y, month: m, day, hour, minute }, { zone: ZONE });
  return dt.isValid ? dt : null;
}
const statusOf = r => String(r.status || 'pending').toLowerCase().trim().replace(/[\s-]+/g, '_');
const firstName = n => String(n || '').trim().split(/\s+/)[0] || '';
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
function emailLayout(title, paragraphs, button) {
  const btn = button && button.url ? `<p style="margin:24px 0"><a href="${esc(button.url)}" style="background:#111;color:#fff;padding:12px 20px;border-radius:8px;text-decoration:none;font-weight:bold">${esc(button.text)}</a></p>` : '';
  return `<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:auto;color:#222;line-height:1.5">
<h2 style="margin-bottom:8px">${esc(title)}</h2>${paragraphs.map(p => `<p>${p}</p>`).join('')}${btn}
<p style="color:#777;font-size:13px;border-top:1px solid #eee;padding-top:12px">${esc(cfg.business_name)} · ${esc(cfg.business_address)} · ${esc(cfg.business_phone)}</p></div>`;
}
// ===== End of helpers =====

const now = DateTime.now().setZone(ZONE);
const hoursBefore = Number(cfg.hours_before) || 24;
const windowEnd = now.plus({ hours: hoursBefore });
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (!String(r.id ?? '').trim()) continue;                       // rows without an id are ignored
  if (SKIP_STATUSES.includes(statusOf(r))) continue;              // cancelled, completed or no-show
  if (String(r.reminder_sent ?? '').trim()) continue;             // already reminded (or failed, see notes)
  const email = String(r.email ?? '').trim();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) continue;        // no valid email address
  const dt = parseAppointment(r);
  if (!dt || dt <= now || dt > windowEnd) continue;               // outside the reminder window
  const a = {
    id: String(r.id), client_name: String(r.client_name ?? ''), first_name: firstName(r.client_name) || 'there', email,
    service: String(r.service || 'your appointment'), staff: String(r.staff ?? ''),
    date_text: dt.setLocale(LOCALE).toFormat('cccc, d LLLL'), time_text: dt.setLocale(LOCALE).toFormat('t'),
  };
  // ===== EMAIL TEXT (edit freely) =====
  a.subject = `Reminder: your appointment at ${cfg.business_name} on ${a.date_text} at ${a.time_text}`;
  a.html = emailLayout(`Hi ${a.first_name}!`, [
    `This is a friendly reminder of your <b>${esc(a.service)}</b> appointment${a.staff ? ' with ' + esc(a.staff) : ''} on <b>${esc(a.date_text)} at ${esc(a.time_text)}</b>.`,
    `If you can't make it, please let us know as soon as possible by replying to this email or calling ${esc(cfg.business_phone)}, so someone else can take the slot.`,
    cfg.maps_link ? `<a href="${esc(cfg.maps_link)}">Get directions</a>` : ''].filter(Boolean),
    { text: 'Change or cancel my appointment', url: cfg.booking_link });
  // ====================================
  out.push({ json: a });
}
return out;
